content:
Roomopolis позволяет создавать пользовательские ключи через Kubejs для размещения шаблонов в мире. Ключи можно создавать в Kubejs.



StartupEvents.registry('item', event => {
    //Создайте пользовательский ключ-предмет следующим образом
    event.create("test_key", 'roomopolis_key')
        //Укажите строковое расположение шаблона, который вы хотите спавнить; пример файла находится здесь: data/roomopolis/structures/tiny_room.nbt
        .templateId("roomopolis:tiny_room")
        //Структура всегда размещается на один блок позади блока, на который нажал игрок; регулировка высоты позволяет настроить положение шаблона по высоте
        .heightAdjustment(1)
        //keyBlock является необязательным и не требуется; если здесь задан блок, ключи будут работать только на этом блоке
        .keyBlock("minecraft:iron_block")
})

